for locale, translated in pairs(stackEditorValues) do
    local target = locales[locale]
    if type(target) == "table" then
        for index, key in ipairs(stackEditorKeys) do target[key] = translated[index] end
    end
end
if type(locales.esMX) == "table" then
    for index, key in ipairs(stackEditorKeys) do locales.esMX[key] = stackEditorValues.esES[index] end
end

