for locale, translated in pairs(customEngineValues) do
    local target = locales[locale]
    if type(target) == "table" then
        for index, key in ipairs(customEngineKeys) do target[key] = translated[index] end
    end
end
if type(locales.esMX) == "table" then
    for index, key in ipairs(customEngineKeys) do locales.esMX[key] = customEngineValues.esES[index] end
end

